-- PYTH BOMB · Classic ESPECIAL DE NOVEMBRO (Halls, 2026-11-26)
-- Rode no Supabase SQL Editor. Pode rodar de novo sem duplicar nem bagunçar.
-- O que faz:
--   1. GUARDA o estado atual do Classic (coluna classic_on_prev) só na primeira vez (reversível).
--   2. DESLIGA todas as perguntas do Classic (nada é apagado; só saem do sorteio).
--   3. LIGA 154 perguntas novas, só com fatos dos Pythian Bulletins de novembro/2026 (A/B/C/D).
-- Para VOLTAR ao Classic de antes depois do evento, rode:  update public.questions set classic_on = classic_on_prev;
-- (e, se não quiser mais as de novembro:  update public.questions set classic_on = false where source_reference like 'nov-bulletin |%';)

-- 1) fotografia do estado atual, uma única vez
alter table public.questions add column if not exists classic_on_prev boolean;
update public.questions set classic_on_prev = classic_on where classic_on_prev is null;

-- 2) desliga tudo do Classic
update public.questions set classic_on = false;

-- 3) insere as perguntas de novembro (mesmo formato do 044: kind 'choice', 3 alternativas erradas)
on conflict do nothing;

-- garante que SÓ as de novembro fiquem ligadas no Classic (seguro em re-execução)
update public.questions set classic_on = true, active = false, kind = 'choice'
  where source_reference like 'nov-bulletin |%';

-- conferência: deve mostrar o total de perguntas de novembro ligadas e 0 de outras
select
  count(*) filter (where classic_on and source_reference like 'nov-bulletin |%') as november_on,
  count(*) filter (where classic_on and source_reference not like 'nov-bulletin |%') as other_on,
  count(*) filter (where classic_on and kind = 'choice') as classic_total
from public.questions;
